#!/usr/bin/env node
/* eslint-disable @typescript-eslint/no-require-imports */
'use strict';

const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');

function getArg(name) {
  const idx = process.argv.indexOf(name);
  return idx === -1 ? null : (process.argv[idx + 1] ?? '');
}

function gh(args) {
  return execFileSync('gh', args, {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

function getManualLabels() {
  const policyFile =
    getArg('--policy-file') ||
    path.join(process.cwd(), '.github', 'workflows', 'policy.json');
  try {
    const policy = JSON.parse(fs.readFileSync(policyFile, 'utf8'));
    const labels = policy?.auditSafe?.manualLabels;
    if (Array.isArray(labels) && labels.length > 0) return labels.join(',');
  } catch {
    // fall through to default
  }
  return 'auto-fix,needs-review';
}

/**
 * Build a starvation alert issue body from telemetry.
 * @param {object} telemetry - Output from computeQueueLatencyTelemetry
 * @param {string} runUrl - URL of the workflow run that detected the alert
 * @returns {string} Markdown issue body
 */
function buildAlertBody(telemetry, runUrl) {
  if (!telemetry || !telemetry.percentiles) {
    throw new Error(
      'buildAlertBody requires telemetry with computed percentiles',
    );
  }
  const p = telemetry.percentiles;
  const thresholdLine =
    'p95 > ' + telemetry.threshold + 's (actual: **' + p.p95 + 's**)';
  const sampleLine =
    'Sample count: ' + telemetry.sampleCount + ' jobs in the window';

  const lines = [
    '## Queue Starvation Alert',
    '',
    '**Run:** ' + runUrl,
    '**Threshold:** ' + thresholdLine,
    '**' + sampleLine + '**',
    '',
    '### Queue Latency Percentiles',
    '',
    '| Percentile | Latency |',
    '| ---------- | ------- |',
    '| p50        | ' + p.p50 + 's   |',
    '| p75        | ' + p.p75 + 's   |',
    '| p95        | ' + p.p95 + 's   |',
    '| p99        | ' + p.p99 + 's   |',
    '| max        | ' + p.max + 's   |',
    '',
    '### Possible Causes',
    '',
    '- Runner pool exhaustion (all runners busy, jobs queue)',
    '- Scheduled cron collision (multiple workflows fire simultaneously)',
    '- Long-running job holding a concurrency slot',
    '- GitHub Actions infrastructure congestion',
    '',
    '---',
    'Generated by workflow-health-optimize (WHO-E03).',
  ];
  return lines.join('\n');
}

/**
 * File or comment on a queue starvation alert issue.
 * @param {object} opts
 * @param {string} opts.repo - GitHub repo (owner/repo)
 * @param {object} opts.telemetry - Telemetry from computeQueueLatencyTelemetry
 * @param {string} opts.runUrl - Workflow run URL
 * @param {boolean} [opts.dryRun] - Skip issue creation
 * @returns {{ action: string, issue?: object }}
 */
function fileQueueStarvationAlert({ repo, telemetry, runUrl, dryRun }) {
  const title =
    '[workflow-health] Queue starvation — p95 queue latency exceeded threshold';
  const body = buildAlertBody(telemetry, runUrl);

  // Search for existing open starvation alert issue
  try {
    const existing = JSON.parse(
      gh([
        'issue',
        'list',
        '--repo',
        repo,
        '--state',
        'open',
        '--search',
        'in:title "Queue starvation"',
        '--json',
        'number,url',
        '--limit',
        '1',
      ]).trim(),
    );

    if (existing.length > 0) {
      if (!dryRun) {
        const ts = new Date().toISOString();
        gh([
          'issue',
          'comment',
          String(existing[0].number),
          '--repo',
          repo,
          '--body',
          '## Recurrence at ' + ts + '\n\n' + body,
        ]);
      }
      return { action: 'commented', issue: existing[0] };
    }
  } catch (err) {
    console.error('Search for existing issue failed: ' + err.message);
  }

  if (dryRun) {
    return { action: 'dry-run-create' };
  }

  try {
    const output = gh([
      'issue',
      'create',
      '--repo',
      repo,
      '--title',
      title,
      '--body',
      body,
      '--label',
      getManualLabels(),
    ]);
    const match = output.match(/\/issues\/(\d+)/);
    return {
      action: 'created',
      issue: {
        number: match ? match[1] : 'unknown',
        url: output.trim(),
      },
    };
  } catch (e) {
    return { action: 'error', error: e.message };
  }
}

module.exports = { buildAlertBody, fileQueueStarvationAlert, getManualLabels };

if (require.main === module) {
  const repo = getArg('--repo') || process.env.GITHUB_REPOSITORY;
  const telemetryArg = getArg('--telemetry');
  const runUrl = getArg('--run-url') || '';
  const dryRun = process.argv.includes('--dry-run');

  if (!telemetryArg) {
    console.error(
      'Usage: file-queue-starvation-alert.cjs --repo <repo> --telemetry <json> --run-url <url>',
    );
    process.exit(1);
  }

  let telemetry;
  try {
    telemetry = JSON.parse(telemetryArg);
  } catch (err) {
    console.error('Invalid --telemetry JSON: ' + err.message);
    process.exit(1);
  }

  // Starvation alerts require computed percentiles; empty/no-data telemetry
  // would otherwise throw a deep TypeError inside buildAlertBody.
  if (!telemetry || !telemetry.percentiles) {
    console.error(
      'Telemetry has no percentile data (no queue samples); nothing to alert.',
    );
    process.exit(1);
  }

  const result = fileQueueStarvationAlert({ repo, telemetry, runUrl, dryRun });
  console.log(JSON.stringify(result, null, 2));
  if (result.action === 'error') {
    process.exit(1);
  }
}
